&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;See Our High-Performing Culture &amp;gt;&amp;gt;&amp;gt;&lt;/span&gt;&lt;a href=&quot;https://www.instagram.com/lifeatshipbob/&quot;&gt; &lt;/a&gt;&lt;a href=&quot;https://www.instagram.com/lifeatshipbob/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Check us out on Instagram&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt; (@lifeatshipbob)&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:240}&quot;&gt;#LI-AD1&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;TextRun SCXW177749497 BCX0&quot; lang=&quot;EN&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW177749497 BCX0&quot;&gt;We recognize that people come with a wealth of experience and talent beyond just the technical requirements of a job. If your experience is close to what you see listed here, please still consider applying. Diversity of experience and skills combined with passion is a key to innovation and excellence; therefore, we encourage people from all backgrounds to apply to our positions.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW177749497 BCX0&quot;&gt;&lt;span class=&quot;SCXW177749497 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About You:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Building the world’s leading&amp;nbsp;full-stack fulfillment platform&amp;nbsp;is&amp;nbsp;challenging&amp;nbsp;work. The problems we solve are complex, the pace is fast, and the bar is high.&amp;nbsp;That means&amp;nbsp;ShipBob’s&amp;nbsp;environment&amp;nbsp;isn’t&amp;nbsp;the right&amp;nbsp;fit for everyone, and&amp;nbsp;that’s&amp;nbsp;okay.&amp;nbsp;If you are ready to take ownership,&amp;nbsp;push boundaries, and&amp;nbsp;grow alongside a team that genuinely supports each other, we would love to hear from you.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Learn more about our core values and how we perform at a high level in our day-to-day work on our Culture page (&lt;/span&gt;&lt;a href=&quot;https://www.shipbob.com/careers/culture/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.shipbob.com/careers/culture/&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;).&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW177749497 BCX0&quot; style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW177749497 BCX0&quot; lang=&quot;EN&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW177749497 BCX0&quot;&gt;About Us: &lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;/strong&gt;&lt;br class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW177749497 BCX0&quot; style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;span class=&quot;TextRun Highlight SCXW177749497 BCX0&quot; lang=&quot;EN&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW177749497 BCX0&quot;&gt;ShipBob is a leading global supply chain and fulfillment technology platform designed for SMB and Mid-Market ecommerce merchants to provide them access to best-in-class capabilities and to deliver a delightful shopper experience. Merchants can outsource their entire fulfillment operations, utilize &lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW177749497 BCX0&quot;&gt;ShipBob’s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW177749497 BCX0&quot;&gt; proprietary warehouse management system for in-house fulfillment, or take advantage of a hybrid solution across &lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW177749497 BCX0&quot;&gt;ShipBob’s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW177749497 BCX0&quot;&gt; dozens of fulfillment center network in the United States, Canada, United Kingdom, Europe, and Australia. &lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW177749497 BCX0&quot;&gt;ShipBob&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW177749497 BCX0&quot;&gt; is backed by leading investors like Menlo Ventures, Bain Capital Ventures, Hyde Park Venture Partners, and SoftBank Vision Fund 2, and is one of the fastest-growing tech companies headquartered in Chicago.&lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;br class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW177749497 BCX0&quot; style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;At ShipBob, every full-time employee gets access to our best-in-class AI and productivity tools from Day 1 at no cost. This isn&#39;t a pilot or a perk for select teams. It&#39;s standard for everyone. We believe innovation isn&#39;t owned by one department. Whether you&#39;re in Talent, Operations, Finance, Engineering, or Customer Success, we expect you to ask: &lt;em&gt;how can this be done better, faster, or smarter?&lt;/em&gt; These tools are our investment in your ability to find those answers.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW177749497 BCX0&quot; style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;&lt;strong&gt;Use of AI-Assisted Tools During Recruitment&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;/p&gt;
&lt;p&gt;We may use AI-assisted tools during the recruitment process to support administrative functions such as transcribing interviews, generating summaries or notes, organizing interview feedback, facilitating candidate communications, and helping recruiters identify candidates whose qualifications may align with job requirements. These tools are designed to assist our recruiting team and are not used to make final hiring decisions.&amp;nbsp;Hiring decisions are made by trained human reviewers who consider the candidate&#39;s application, interview performance, qualifications, experience, and other relevant factors. AI-assisted tools do not independently determine whether a candidate advances in the hiring process or receives an offer of employment.&amp;nbsp;Where required by applicable law, candidates will be provided with notice regarding our use of AI-assisted technologies and, where available, information about any applicable rights relating to such processing, including the ability to request additional information or opt out of certain AI-assisted processing activities. Candidates who exercise available opt-out rights may be reviewed through alternative processes consistent with applicable law.&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW177749497 BCX0&quot; style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;em&gt;&lt;span class=&quot;TextRun SCXW263457653 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW263457653 BCX0&quot;&gt;ShipBob provides equal employment opportunities to all employees and applicants for employment and prohibits discrimination and harassment of any type without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other characteristic protected by federal, state or local laws.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW263457653 BCX0&quot;&gt;&lt;span class=&quot;SCXW263457653 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br class=&quot;SCXW263457653 BCX0&quot;&gt;&lt;/span&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW263457653 BCX0&quot;&gt;&lt;span class=&quot;SCXW263457653 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br class=&quot;SCXW263457653 BCX0&quot;&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW263457653 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW263457653 BCX0&quot;&gt;This policy applies to all terms and conditions of employment, including recruiting, hiring, placement, promotion, termination, layoff, recall, transfer, leaves of absence, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW263457653 BCX0&quot;&gt;c&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW263457653 BCX0&quot;&gt;ompensation&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW263457653 BCX0&quot;&gt;and training.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW263457653 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW177749497 BCX0&quot; style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;SCXW177749497 BCX0&quot;&gt;&lt;em&gt;&lt;span class=&quot;EOP SCXW263457653 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;&lt;strong&gt;There is no deadline to apply for this position, as ShipBob accepts applications on an ongoing basis&lt;/strong&gt;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;col-lg-6 content&quot;&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;Hybrid role (3 days in the office, 2 days remote), based in our London office at HYLO, 103–105 Bunhill Row, London EC1Y 8LZ.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;p&gt;At JFrog, we’re reinventing DevOps to help the world’s greatest companies innovate -- and we want you along for the ride. This is a special place with a unique combination of brilliance, spirit and just all-around great people. Here, if you’re willing to do more, your career can take off. And since software plays a central role in everyone’s lives, you’ll be part of an important mission. Thousands of customers, including the majority of the Fortune 100, trust JFrog to manage, accelerate, and secure their software delivery from code to production -- a concept we call “liquid software.” Wouldn&#39;t it be amazing if you could join us in our journey?&lt;/p&gt;
&lt;p&gt;We are looking for a Solutions Engineer to be on the front lines, working closely with our strategic customers and prospects, guiding them on how to build robust and secured business critical DevOps and software development processes in the age of agentic development. You will work with our Sales, Product &amp;amp; Engineering teams to help customers understand the value of JFrog solutions from a technical and business perspective. If you love working with brilliant people, being part of an energetic team and changing the world of software, you might be the perfect Frog to join our team!&lt;/p&gt;
&lt;h5&gt;&lt;strong&gt;As a Senior Solutions Engineer at JFrog you will...&lt;/strong&gt;&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;Engage with customers to ensure their success in their DevOps and DevSecOps&amp;nbsp; journey leveraging the JFrog Platform&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Support JFrog&#39;s Technical Selling motion and significantly contribute to the customer journey to build technical win and championship&lt;/li&gt;
&lt;li&gt;Showcase JFrog’s technology and success in events and conferences&lt;/li&gt;
&lt;li&gt;Influence the features and roadmap of JFrog products based on customer needs&lt;/li&gt;
&lt;li&gt;Stay current with the latest technology trends related to the DevOps and DevSecOps landscape&lt;/li&gt;
&lt;/ul&gt;
&lt;h5&gt;&lt;strong&gt;To be a Senior Solution Engineer at JFrog you need...&lt;/strong&gt;&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;1+ years experience in Technical Sales or Sales Engineering positions&lt;/li&gt;
&lt;li&gt;Experience in building relationships with customers’ champions and senior stakeholders&lt;/li&gt;
&lt;li&gt;Proven experience in Docker, Kubernetes, CI/CD, git integrations and&amp;nbsp; build tools&lt;/li&gt;
&lt;li&gt;Hands-on experience with AppSec tools (part or all) such as: SCA / SAST / SBOM Management / Container Security&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Ability to build software pipelines with various DevOps tools&lt;/li&gt;
&lt;li&gt;Hands-on experience with cloud infrastructures - AWS / Azure / GCP - Mandatory&lt;/li&gt;
&lt;li&gt;Hands-on experience with agentic development workflows and understanding of related technical elements: LLMs, MCPs, skills and prompts - Mandatory&lt;/li&gt;
&lt;li&gt;Previous experience in software development role - is an advantage&lt;br&gt;
&lt;div class=&quot;mt-3 w-full empty:hidden&quot;&gt;
&lt;div class=&quot;text-center&quot;&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142); font-family: helvetica, arial, sans-serif;&quot;&gt;About Baringa&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;Baringa is a global consulting firm that partners with leaders to drive change and create value. With deep industry expertise, and enabled by advanced technology, the firm helps clients to deliver with greater confidence and certainty. With over 2,000 people across the UK, Europe, North America, Asia and Australia, the firm combines global insight with local understanding.&lt;/p&gt;
&lt;p&gt;The firm works across energy and resources, financial services, government and public sector, consumer products and retail, pharmaceuticals and life sciences, manufacturing, and technology, media and telecoms, with capabilities spanning strategy, transformation and operational excellence – all powered by advanced technology, data, AI and digital innovation.&lt;/p&gt;
&lt;p&gt;Clients value Baringa’s collaborative approach and the way its teams integrate seamlessly – all working with a shared understanding of what matters most. The firm is known for its kind, curious experts who listen closely and care deeply about client success as they help clients transform energy markets, modernise financial platforms, expand telecoms and digital networks through advanced data analytics, enable digital services in government, and unlock growth in consumer sectors.&lt;/p&gt;
&lt;p&gt;Certified as a&amp;nbsp;&lt;em&gt;Great Place to Work &lt;/em&gt;around the world, Baringa has been recognised by the &lt;em&gt;Financial Times &lt;/em&gt;in 22 categories of its UK Leading Management Consultants rankings, and by &lt;em&gt;Forbes &lt;/em&gt;for four consecutive years as one of the World’s Best Management Consulting Firms.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; color: rgb(0, 53, 142);&quot;&gt;Our Governance, Risk &amp;amp; Compliance practice are looking for a Director with a strong commercial track record to join the team.&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;Baringa is building the world&#39;s most trusted consulting firm. We work with everyone from FTSE 100 names to bright new start-ups, in every sector. We have hubs in Europe, the US, Asia and Australia and bring deep industry expertise enabled by advanced technology to help clients deliver with greater confidence and certainty.&lt;/p&gt;
&lt;p&gt;Our Financial Services GR&amp;amp;C practice helps leading banking and insurance clients navigate an increasingly complex risk and regulatory environment to proactively manage and future-proof risk and compliance functions so they are streamlined, scalable and fit for the future. We support clients across economic crime, conduct &amp;amp; compliance, operational risk &amp;amp; resilience, data, digital &amp;amp; cyber risk, treasury &amp;amp; liquidity risk and climate risk &amp;amp; sustainability. All underpinned by our AI, data and technology capability.&lt;/p&gt;
&lt;p&gt;As the market continues to evolve, we are investing in our Governance, Risk &amp;amp; Compliance capability and are seeking a Director with a strong commercial track record to help shape the next phase of growth.&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;strong&gt;What you will be doing&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead large-scale risk, regulation and compliance transformation programmes for leading Financial Services organisations.&lt;/li&gt;
&lt;li&gt;Advise Boards, Board Risk Committees, Executive Committees and senior risk leaders on risk strategy, governance, controls and operating model effectiveness.&lt;/li&gt;
&lt;li&gt;Help clients design and implement enterprise-wide risk frameworks, governance structures and control environments&lt;/li&gt;
&lt;li&gt;You will lead complex engagements across operational risk, compliance, conduct risk, regulatory change and broader non-financial risk agendas, or within financial risk – specifically treasury and liquidity&lt;/li&gt;
&lt;li&gt;Identify and originate new opportunities within existing and prospective client accounts, supporting the continued growth of the practice.&lt;/li&gt;
&lt;li&gt;Build trusted relationships with senior stakeholders across UK Financial Services organisations.&lt;/li&gt;
&lt;li&gt;Contribute to the development of Baringa’s propositions, intellectual property and thought leadership.&lt;/li&gt;
&lt;li&gt;Support the growth of emerging capabilities including AI governance, AI risk management, digital asset risk and compliance frameworks.&lt;/li&gt;
&lt;li&gt;Coach, mentor and develop consultants and future leaders within the team.&lt;/li&gt;
&lt;li&gt;You will play an active role in shaping the long-term strategic direction of the Risk practice, with a clear pathway towards equity Partner.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;strong&gt;Your skills and experience &lt;br&gt;&lt;/strong&gt;&lt;/span&gt;&lt;br&gt;You will have significant experience across multiple areas of financial or non-financial risk, including:&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Broad Governance, Risk &amp;amp; Compliance Expertise&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You will have significant experience across multiple areas of financial or non-financial risk, including:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Enterprise Risk Management&lt;/li&gt;
&lt;li&gt;Risk Governance and Framework Design&lt;/li&gt;
&lt;li&gt;Operational Risk&lt;/li&gt;
&lt;li&gt;Compliance and Conduct Risk&lt;/li&gt;
&lt;li&gt;Regulatory Change&lt;/li&gt;
&lt;li&gt;Controls Frameworks and Assurance&lt;/li&gt;
&lt;li&gt;Risk Operating Model Design&lt;/li&gt;
&lt;li&gt;Risk Transformation Programmes&lt;/li&gt;
&lt;li&gt;Treasury and liquidity risk&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;We are particularly interested in individuals who bring broad risk advisory expertise rather than a highly specialised niche focus.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Growth and Emerging Risk Capabilities&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You will have experience in one or more of the following strategic growth areas:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;AI Governance and Risk Management&lt;/li&gt;
&lt;li&gt;Digital Asset Risk and Compliance frameworks&lt;/li&gt;
&lt;li&gt;Experience helping clients respond to evolving regulatory expectations and emerging technologies.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Commercial and Client Leadership&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A proven track record of developing trusted client relationships and growing strategic accounts.&lt;/li&gt;
&lt;li&gt;Strong commercial instincts and an ability to identify and shape consulting opportunities.&lt;/li&gt;
&lt;li&gt;Experience leading the origination and expansion of consulting engagements.&lt;/li&gt;
&lt;li&gt;Credibility with C-suite, Board and senior executive stakeholders.&lt;/li&gt;
&lt;li&gt;A recognised market profile within UK Financial Services.&lt;/li&gt;
&lt;li&gt;Demonstrable experience contributing to business development and practice growth.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Financial Services Network&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong relationships across the UK Financial Services market.&lt;/li&gt;
&lt;li&gt;Experience working with leading banking organisations such as Large Global retail banks and other Tier 1 institutions.&lt;/li&gt;
&lt;li&gt;The ability to engage executive stakeholders and establish new client conversations.&lt;/li&gt;
&lt;li&gt;A strong understanding of the strategic, regulatory and risk challenges facing the sector.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Leadership&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Leading complex transformation programmes and multi-disciplinary teams.&lt;/li&gt;
&lt;li&gt;Developing, coaching and inspiring high-performing consultants.&lt;/li&gt;
&lt;li&gt;Building propositions and contributing to thought leadership.&lt;/li&gt;
&lt;li&gt;Acting as a trusted adviser to senior client stakeholders.&lt;/li&gt;
&lt;li&gt;Supporting succession planning and capability development.&lt;/li&gt;
&lt;li&gt;Demonstrating the attributes and potential required for future progression to Partner.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;What a career at Baringa will give you&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;h3&gt;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;Putting&lt;/span&gt; &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span style=&quot;color: rgb(208, 0, 111);&quot;&gt;People&lt;/span&gt; &lt;/span&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;First.&lt;/span&gt; &lt;/span&gt;&lt;/h3&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Baringa is a People First company and wellbeing is at the forefront of our culture. We recognise the importance of work-life balance and flexible working and provide our staff amazing benefits. Some of these benefits include:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Generous Annual Leave Policy:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We recognise everyone needs a well-deserved break. We provide our employees with 5 weeks of annual leave, fully available at the start of each year. In addition to this, we have introduced our 5-Year Recharge benefit which allows all employees an additional 2 weeks of paid leave after 5 years continuous service.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Flexible Working:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We know that the ‘ideal’ work-life balance will vary from person to person and change at different stages of our working lives. To accommodate this, we have implemented a hybrid working policy and introduced more flexibility around taking unpaid leave.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Corporate Responsibility Days:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; Our world is important to us, so all our employees get 3 every year to help social and environmental causes and increase our impact on the communities that mean the most to us.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Wellbeing Fund:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We want to encourage all employees to take charge and prioritise their own wellbeing. We’ve introduced our annual People Fund to support this by offering every individual a fund to support and manage their wellbeing through an activity of their choice.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Profit Share Scheme:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; All employees participate in the Baringa Group Profit Share Scheme so everyone has a stake in the company’s success.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot; data-contrast=&quot;none&quot;&gt;Diversity and Inclusion&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We are proud to be an Equal Opportunity Employer. We believe that creating an environment where everyone feels a sense of belonging is central to our culture and that diversity is paramount to driving creativity, innovation, and value for our clients and for our people.&lt;/span&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot; data-contrast=&quot;none&quot;&gt;An award-winning workplace&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;You can be a part of our ‘Great Place to Work’ – with our commitment to women and well-being in the workplace for all. &lt;/span&gt;&lt;a href=&quot;https://www.baringa.com/en/impact/awards/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Click here&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt; to see some of our recent awards and how we’ve achieved this.&lt;/span&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Using business as a force for good.&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We maintain high standards of environmental performance and transparency, which can be seen through our commitment to Net Zero with our SBTI-verified Scope 1, 2 and 3 emissions reduction targets and our support of the Better Business Act. We report our progress publicly and ensure that we are also externally assessed and scored through organisations like CDP and EcoVadis - helping us to continually identify where we can improve.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We have a long legacy of supporting the communities in which we work, and offer a variety of ways to contribute, by putting people first and creating impact that lasts. Our Corporate Social Responsibility (CSR) agenda is about giving back to the communities in which we live and work by sharing our skills, talent and time. In essence, we aim to empower and encourage everyone in the firm to contribute to the things we care about, and support registered charities and organisations with a clear social or environmental purpose to increase the positive impact they can have.&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;&lt;span style=&quot;color: rgb(208, 0, 111); font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;Join us&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;All applications received will be reviewed by a member of our Talent Acquisition team. We never rely solely on automated screening or AI tools to make hiring decisions. Your application will be considered for employment without regard to race, ethnicity, religion, gender, gender identity or expression, sexual orientation, nationality, disability, age, faith or social background. We do not filter applications by university background and encourage those who have taken alternative educational and career paths to apply. We would like to actively encourage applications from those who identify with less represented and minority groups. We operate an inclusive recruitment process, ensuring reasonable adjustments where needed. Please contact a member of our Recruitment Team to discuss further.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(208, 0, 111); font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;Baringa Privacy Notices&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For UK &amp;amp; EU&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data will be retained by Baringa for up to two years, in accordance with our &lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-004-ukrpn---uk-recruitment-privacy-notice-pdf.pdf&quot;&gt;UK Recruitment Privacy Notice / &lt;/a&gt;&lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-005-eurpn---eu-recruitment-privacy-notice-pdf.pdf&quot;&gt;EU Recruitment Privacy Notice&lt;/a&gt;, to evaluate your application and meet our legal and reporting obligations. In line with the General Data Protection Regulation (GDPR), you have the right to request access to, rectification, or erasure (subject to legal limitations) of your personal data. For more information, please contact us at &lt;a ----------
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For the USA&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data may be retained by Baringa for up to two years, as outlined in our&amp;nbsp;&lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-007-nerpn-amer--apac-recruitment-privacy-notice-word.pdf&quot;&gt;Recruitment Privacy Notice (AMER &amp;amp; APAC)&lt;/a&gt;, to support the recruitment process and internal reporting requirements. Where applicable, and in accordance with relevant federal and state laws, you may have the right to request access to or correction of your personal information. For further details, please contact &lt;a ----------
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For Australia &amp;amp; Singapore&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data will be retained by Baringa for up to two years, in accordance with our &lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-007-nerpn-amer--apac-recruitment-privacy-notice-word.pdf&quot;&gt;Recruitment Privacy Notice (AMER &amp;amp; APAC)&lt;/a&gt;, to assess your application and meet applicable reporting and legal obligations. In line with the Australian Privacy Act and Singapore’s Personal Data Protection Act (PDPA), you may have rights to access, correct, or request limited deletion of your personal data. For more information, please contact us at &lt;a ----------<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Since 2004, we’ve been bringing investment ideas to life and connecting capital with the right people and opportunities. Today, we manage more than £2.5 billion for a broad range of investors across five key investment strategies: Private Credit,&amp;nbsp;Social Housing, Clean Heat, Energy and Venture. These strategies underpin the innovative range of investments we offer to both private (retail) and institutional clients.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;There are 230+ employees at Triple Point, all committed to leaving the world demonstrably better than we found it. That’s why we’re a certified B Corp, signed up to the Principles for Responsible Investment, and were named a Sunday Times &lt;em&gt;&#39;Best Place to Work&amp;nbsp; 2025 &amp;amp; 2026&#39;&lt;/em&gt;. &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;I&lt;/strong&gt;&lt;strong&gt;f this sounds like an environment where you would flourish, then read on…&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;table style=&quot;width: 844px;&quot; width=&quot;642&quot;&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td style=&quot;width: 828.719px;&quot; width=&quot;642&quot;&gt;
&lt;p&gt;&lt;strong&gt;The Function &amp;amp; Team&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Relationship Services team is Triple Point Private Credit&#39;s &lt;strong&gt;SME Portfolio team&lt;/strong&gt;. The team manages borrower relationships across SME Debt Finance, Specialty Finance and Fund Finance, ensuring strong portfolio performance, assessing in-life credit events, and supporting high-quality client outcomes.&lt;/p&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&quot;width: 828.719px;&quot; width=&quot;642&quot;&gt;
&lt;p&gt;&lt;strong&gt;Role Purpose&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Associate Director (AD) will own and lead borrower relationships across an assigned SME lending portfolio, ensuring strong portfolio performance, proactive risk management, and high-quality client engagement. The role requires analytical strength, sound judgement, and the ability to structure solutions that balance commercial, and risk considerations.&lt;/p&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&quot;width: 828.719px;&quot; width=&quot;642&quot;&gt;
&lt;p&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Portfolio &amp;amp; Relationship Management&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead the relationship with an allocated portfolio of borrowers, acting as the primary point of contact and ensuring a high-quality client experience.&lt;/li&gt;
&lt;li&gt;Conduct quarterly client calls/meetings, including reviewing MI and providing follow-up actions.&lt;/li&gt;
&lt;li&gt;Identify opportunities to deepen relationships or develop new lending opportunities.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Risk, Compliance &amp;amp; Monitoring&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Own portfolio compliance: timely collection of MI, covenant testing, annual reviews, KYC refresh, and ensuring no overdue portfolio actions.&lt;/li&gt;
&lt;li&gt;Lead early identification and escalation of underperformance, arrears, emerging risks or covenant pressure.&lt;/li&gt;
&lt;li&gt;Analyse management accounts to identify trends, risks and early warning indicators.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Credit, Restructuring &amp;amp; In-Life Events&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead borrower requests such as covenant resets, waivers, forbearance, restructures and new money requests.&lt;/li&gt;
&lt;li&gt;Draft high-quality credit papers and present recommendations to Credit Forum or Investment Committee.&lt;/li&gt;
&lt;li&gt;Negotiate directly with clients to achieve balanced, commercially robust outcomes.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;New Money / Modifications&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead deal structuring, including drafting term sheets and coordinating with internal and external legal advisers on documentation.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Collaboration &amp;amp; Leadership&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Work closely with Portfolio Managers to manage workload, prioritisation and delivery.&lt;/li&gt;
&lt;li&gt;Escalate sensitive or complex matters appropriately to the Relationship Director or Head of Team.&lt;/li&gt;
&lt;li&gt;Support consistent best practice across the Relationship Services team.&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&quot;width: 828.719px;&quot; width=&quot;642&quot;&gt;
&lt;p&gt;&lt;strong&gt;Knowledge &amp;amp; Experience&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong ability to interpret and analyse company financial statements and management information.&lt;/li&gt;
&lt;li&gt;Experience writing and reviewing credit applications from a front-office or credit role.&lt;/li&gt;
&lt;li&gt;Experience in financial modelling.&lt;/li&gt;
&lt;li&gt;Experience negotiating with borrowers, structuring transactions, and handling restructures or covenant issues (desirable).&lt;/li&gt;
&lt;li&gt;Knowledge of SME debt finance; experience across Wholesale Finance or Structured Finance (desirable).&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&quot;width: 828.719px;&quot; width=&quot;642&quot;&gt;
&lt;p&gt;&lt;strong&gt;Competencies&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Highly numerate, analytical and comfortable dealing with complexity.&lt;/li&gt;
&lt;li&gt;Proactive, self-starter with ownership mindset.&lt;/li&gt;
&lt;li&gt;Strong communication and interpersonal skills, able to build collaborative and constructive relationships at all levels.&lt;/li&gt;
&lt;li&gt;Organised and able to prioritise across a varied workload with pace and accuracy.&lt;/li&gt;
&lt;li&gt;Curious and eager to learn; open to feedback and new approaches, including use of AI where relevant.&lt;/li&gt;
&lt;li&gt;Acts with integrity, professionalism and sound judgement.&lt;/li&gt;
&lt;li&gt;Team player who contributes beyond individual responsibilities and supports shared goals.&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&quot;width: 828.719px;&quot; width=&quot;642&quot;&gt;
&lt;p&gt;&lt;strong&gt;Why Join Us&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Be a part of a&lt;strong&gt; forward-thinking, growing&lt;/strong&gt; and &lt;strong&gt;innovative&lt;/strong&gt; company.&lt;/li&gt;
&lt;li&gt;Work with a talented and&lt;strong&gt; driven&lt;/strong&gt; team in a collaborative and connected environment.&lt;/li&gt;
&lt;li&gt;Competitive salary and comprehensive &lt;strong&gt;benefits&lt;/strong&gt; package.&lt;/li&gt;
&lt;li&gt;Opportunities for&lt;strong&gt; professional development&lt;/strong&gt; and career progression.&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&quot;width: 828.719px;&quot; width=&quot;642&quot;&gt;
&lt;p&gt;&lt;strong&gt;High Performance at Triple Point&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;High Performance at Triple Point means living our values at the top of your game.&lt;/p&gt;
&lt;p&gt;Our five values are below, you can read more on our website about how we embed our values to drive a high-performance culture.&lt;/p&gt;
&lt;p&gt;·&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp; Stay Curious&lt;/p&gt;
&lt;p&gt;·&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp; Be Generous&lt;/p&gt;
&lt;p&gt;·&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp; Take Thoughtful Action&lt;/p&gt;
&lt;p&gt;·&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp; Pull Together&lt;/p&gt;
&lt;p&gt;·&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp; Own It&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Triple Point offers a wealth of benefits including a contributory pension, hybrid/flexible working and ongoing learning and development opportunities. Check out our comprehensive list of benefits&amp;nbsp;&lt;a href=&quot;https://www.triplepoint.co.uk/careers/42/&quot;&gt;HERE&lt;/a&gt;.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Apply today for further information!&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;em&gt;Triple Point is dedicated to providing fair and equal opportunities for all individuals, including both current and potential employees. Discrimination of any kind based on factors such as age, disability, gender, sexual orientation, pregnancy, race, ethnicity, religion, gender identity, or marital status is not tolerated by the company.&lt;/em&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;em&gt;Our aim is to create a welcoming and diverse work environment where people from all walks of life feel valued and supported. We actively encourage individuals from various backgrounds to apply for job vacancies and become part of our team.&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;em&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://triplepoint-my.sharepoint.com/:i:/g/personal/michelle_cowell_triplepoint_co_uk/Edi4UkSOPCFCleTaQ7TONfgByul8Y-u39x5vZCCh-yf_Kg?e=3TA8dB&quot; alt=&quot;&quot;&gt;&lt;/em&gt;&lt;strong&gt;STRICTLY NO AGENCIES&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;You can find a link to our candidate privacy notice&lt;strong&gt; &lt;a href=&quot;https://www.triplepoint.co.uk/candidate-privacy-notice/&quot;&gt;HERE.&amp;nbsp;&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;About THG Ingenuity&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;THG Ingenuity is a fully integrated digital commerce ecosystem, designed to power brands without limits. Our global end-to-end tech platform is comprised of three products: THG Commerce, THG Studios, THG Fulfilment.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Each represents a single, unified solution, overcoming challenges and taking brands direct-to-consumer. Our client portfolio includes globally recognised brands such as Coca-Cola, Nestle, Elemis, Homebase, and Proctor &amp;amp; Gamble.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;The Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are seeking a talented and commercially astute Data Scientist to join our dynamic team tackling Fraud, Payments and Finance. In this multi-focus role, you will be responsible for protecting our global e-commerce operations from fraud, optimising our payments performance and driving profitability and automation initiatives within Finance.&lt;/p&gt;
&lt;p&gt;Working with vast, complex datasets, the work will involve combatting online fraud using our award-winning THG Detect platform and driving payments optimisation by increasing authorisation rates, while also using the latest AI software and Google Cloud Platform (GCP) infrastructure to build complex data solutions and applications.&lt;/p&gt;
&lt;p&gt;This role requires a blend of strong technical skills, commercial acumen, and effective communication to translate complex data insights into tangible business value.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Optimise Fraud Detection:&lt;/strong&gt;&amp;nbsp;Continuously improve automated decision-making in our in-house THG Detect platform using machine learning and decision rules.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Enhance Payment Performance:&lt;/strong&gt;&amp;nbsp;Lead data-driven initiatives to boost payment authorisation rates, optimise transaction routing, and reduce costs.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Drive Profitability within Finance:&lt;/strong&gt;&amp;nbsp;Lead automation and profitability initiatives across different areas of Finance.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Communicate Performance:&lt;/strong&gt;&amp;nbsp;Report on all aspects of fraud, payments and finance performance to stakeholders at all levels, including C-level management.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Drive System Improvements:&lt;/strong&gt;&amp;nbsp;Collaborate with Fraud, Payments, Finance and Engineering teams to scope and implement enhancements to detection systems and data pipelines.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Innovate &amp;amp; Automate:&lt;/strong&gt;&amp;nbsp;Proactively identify opportunities to improve detection capabilities, drive profitability, increase payment success, and enhance team efficiency through automation.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proficient with SQL &amp;amp; Python&lt;/li&gt;
&lt;li&gt;Proficient in a data visualisation software (Tableau/Looker/PowerBI/e.t.c.)&lt;/li&gt;
&lt;li&gt;Experience using a variety of machine learning algorithms&lt;/li&gt;
&lt;li&gt;Able to communicate effectively; using data to tell a story and drive business change&lt;/li&gt;
&lt;li&gt;Experience within Google Cloud preferential&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;THG Ingenuity is proud to be a Disability Confident Committed employer. If you are invited to interview, please let us know if there are any reasonable adjustments we can make to the recruitment process that will enable you to perform to the best of your ability.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;THG Ingenuity is committed to creating a diverse &amp;amp; inclusive environment and hence welcomes applications from all sections of the community.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Because of the high volumes of applications our opportunities attract, it sometimes takes us time to review and consider them all. We endeavour to respond to every application we receive within 14 days. If you haven&#39;t heard from us within that time frame or should you have any specific questions about this or other applications for positions at THG Ingenuity please contact one of our &lt;span class=&quot;mark75xs2u5gf&quot; data-markjs=&quot;true&quot; data-ogac=&quot;&quot; data-ogab=&quot;&quot; data-ogsc=&quot;&quot; data-ogsb=&quot;&quot;&gt;Talent&lt;/span&gt; team to discuss further.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;ms-outlook-mobile-reference-message skipProofing&quot;&gt;&lt;strong&gt;About WPP Production&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message skipProofing&quot;&gt;We are WPP Production - the unified global production company that brings together all of WPP&#39;s content producers, studios and craft experts into one connected organisation. We combine world-class human craft with next generation technology to originate, design, and deliver multi-channel content systems at scale. Built for borderless collaboration and powered by deep craft expertise, we are the production engine designed for today&#39;s always on, AI driven marketing world.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About WPP&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;WPP is the trusted growth partner for the world’s leading brands. We unite&amp;nbsp;cutting-edge media intelligence and data solutions, world-class creativity, next-generation production, transformative enterprise solutions and expert strategic counsel&amp;nbsp;in a single company –&amp;nbsp;powered by exceptional talent and our agentic marketing platform, WPP Open,&amp;nbsp;to help our clients navigate change, capture opportunity and deliver transformational growth. For more information, visit&amp;nbsp;&lt;a href=&quot;https://urldefense.com/v3/__http://wpp.com/__;!!JboVxjCXSME!N9KGoZIn5nCC-uOWhEdE-ChrrJuf6TgkLzNNkLaW9BExJsVqZZ_hMSmGbARJ0tdBOnKYM7kEbv5L3ncUpg7-6uEPNdY$&quot; data-outlook-id=&quot;6ded86b6-cde3-4e48-958d-34727f881edd&quot;&gt;WPP.com&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;A Hybrid working model&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;p class=&quot;xmsonormal&quot;&gt;&lt;em&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around 4 days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;What does a Senior Post Producer do at WPP Production?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You’ll play a central role in delivering high-quality post-production projects across edit, grade, VFX, motion, and sound. As a Senior Post Producer you will bridge hands-on production and leadership, managing key projects, supporting producers, and maintaining strong relationships with clients, agencies, and creative partners. You’ll ensure projects run smoothly, budgets are met, and the creative standard remains high across everything that leaves the studio. You’ll be someone who thrives on collaboration, solves problems calmly under pressure, and takes pride in delivering work that looks, sounds, and feels exceptional. The ideal candidate will have experience working with a global technology brand or demonstrate a strong drive and ambition to contribute to a high-calibre account.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;&lt;strong&gt;Production&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li2&quot;&gt;Lead multiple post-production projects from brief to final delivery, managing timelines, budgets and workflows.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Oversee offline, online, grade, VFX, motion graphics and audio, ensuring projects are delivered on time and to a high standard.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Own production workflows, tracking progress, risks and budgets and keeping the Executive Producer informed.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Proactively identify and resolve challenges, balancing creative, technical and commercial priorities.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Manage global workflows across a centralised production hub and continuously improve ways of working.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Explore and implement AI and emerging technologies to improve efficiency, quality and output.&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;&lt;strong&gt;Clients &amp;amp; Collaboration&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li2&quot;&gt;Act as a senior point of contact for clients and agency partners throughout production.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Lead client calls, reviews and presentations, building trusted relationships and managing expectations.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Collaborate closely with creatives, artists, technical teams and senior production leads to deliver high-quality work.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Support and mentor junior and mid-level producers, sharing best practice and fostering a collaborative team environment.&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;&lt;strong&gt;Quality &amp;amp; Commercial&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li2&quot;&gt;Own the studio QC process, ensuring work meets brand, technical and delivery standards.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Develop and implement robust QC workflows and best practices.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Prepare budgets and estimates, maintaining accurate financial tracking and identifying opportunities to improve efficiency.&lt;/li&gt;
&lt;li class=&quot;li2&quot;&gt;Contribute to rate cards, templates and processes that strengthen production and commercial&lt;span class=&quot;s2&quot;&gt;&lt;strong&gt; &lt;/strong&gt;&lt;/span&gt;performance.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li1&quot;&gt;Strong post-production experience across broadcast, digital and social.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Senior-level experience managing complex, high-end campaigns from brief to delivery.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Strong understanding of the full post-production pipeline, including edit, colour, online, VFX and audio.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Proven ability to manage multiple projects, priorities and stakeholders in a fast-paced environment.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Excellent communicator, confident working with clients, agency partners and internal teams.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Experience managing international clients and senior stakeholders across multiple markets.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Calm, organised and solutions-focused, with the ability to stay composed under pressure.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Collaborative team player who leads by example and supports the development of others.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Passionate about craft, creativity, technology and innovation, with a strong eye for detail and efficiency.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Genuine interest in technology brands and the wider tech landscape.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Flexible and adaptable when project deadlines require occasional evening or weekend support. We value work-life balance and these instances are infrequent, with time off in lieu provided where appropriate.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-teams=&quot;true&quot;&gt;#LI-LS1&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Why work here:&amp;nbsp;&lt;br&gt;&lt;/strong&gt;&lt;span data-teams=&quot;true&quot;&gt;At WPP Production, you’ll help shape the future of content production at a truly global scale. We bring together world-class talent, cutting-edge studios, and advanced technology to solve some of the most complex creative and production challenges in the industry. You’ll work in a collaborative, borderless environment where craft excellence is valued, innovation is encouraged, and AI and next-generation tools are used to amplify not replace human creativity. With access to diverse projects, global career opportunities, and the backing of WPP’s unmatched network, this is a place where you can grow your skills, make real impact, and create work that performs for every audience, across every channel, at every moment. &lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Inclusion and Impact&amp;nbsp;&lt;/strong&gt;&lt;br&gt;WPP is an equal opportunity employer and considers applicants for all positions without discrimination or regard to particular characteristics. We are committed to fostering a culture of respect in which everyone feels they belong and has the same opportunities to progress in their careers. &lt;br&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;Data&lt;/strong&gt;&lt;br&gt;We rely on legitimate interest as a legal basis for processing personal information under the GDPR for purposes of recruitment and applications for employment. When you click the &quot;Submit Application&quot; button at the bottom of this page, this will send all the information you have added to WPP Production. Before you do this, we think it&#39;s a good idea to read through our Privacy&amp;nbsp;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;a href=&quot;https://www.hogarthww.com/privacy-policy&quot;&gt;st&lt;/a&gt;&lt;a href=&quot;https://www.hogarth.com/privacy-policy&quot;&gt;atement&lt;/a&gt;.&lt;/span&gt; This explains what we do with your personal data when you apply for a role with us, and, how you can update the information you have provided us with or how to remove it.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;div&gt;
&lt;div&gt;
&lt;p class=&quot;xmsonormal&quot; style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Please contact &lt;a ----- ----- if you need the job advert or form in another format.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;ms-outlook-mobile-reference-message skipProofing&quot;&gt;&lt;strong&gt;About WPP Production&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message skipProofing&quot;&gt;We are WPP Production - the unified global production company that brings together all of WPP&#39;s content producers, studios and craft experts into one connected organisation. We combine world-class human craft with next generation technology to originate, design, and deliver multi-channel content systems at scale. Built for borderless collaboration and powered by deep craft expertise, we are the production engine designed for today&#39;s always on, AI driven marketing world.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About WPP&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;WPP is the trusted growth partner for the world’s leading brands. We unite&amp;nbsp;cutting-edge media intelligence and data solutions, world-class creativity, next-generation production, transformative enterprise solutions and expert strategic counsel&amp;nbsp;in a single company –&amp;nbsp;powered by exceptional talent and our agentic marketing platform, WPP Open,&amp;nbsp;to help our clients navigate change, capture opportunity and deliver transformational growth. For more information, visit&amp;nbsp;&lt;a href=&quot;https://urldefense.com/v3/__http://wpp.com/__;!!JboVxjCXSME!N9KGoZIn5nCC-uOWhEdE-ChrrJuf6TgkLzNNkLaW9BExJsVqZZ_hMSmGbARJ0tdBOnKYM7kEbv5L3ncUpg7-6uEPNdY$&quot; data-outlook-id=&quot;6ded86b6-cde3-4e48-958d-34727f881edd&quot;&gt;WPP.com&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;A Hybrid working model&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;p class=&quot;xmsonormal&quot;&gt;&lt;em&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around four days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What does a Senior Account Manager do at&amp;nbsp;WPP Production?&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;As part of the Client Services Department, you play&amp;nbsp;a central role&amp;nbsp;in the business and are pivotal to the smooth running of your account. You will&amp;nbsp;be required&amp;nbsp;to have a thorough understanding of all areas of the business and&amp;nbsp;be responsible for&amp;nbsp;managing projects from brief to final delivery on time and budget. You will be client focused and require&amp;nbsp;good communication,&amp;nbsp;organisation&amp;nbsp;and time management skills to manage both your clients and internal departments, while always focusing on quality,&amp;nbsp;process&amp;nbsp;and profitability.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What does a Senior Account Manager do at&amp;nbsp;WPP Production, on the TJX account?&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;You will be working within the client’s Activation Account team, implanted onsite working on behalf of the client. You will attend TJX office in Watford&amp;nbsp;two/three times&amp;nbsp;a week and occasionally work from the&amp;nbsp;WPP Production&amp;nbsp;office in London. You will deliver projects, working with TJX’s onsite in-house creative team. You will&amp;nbsp;be responsible for&amp;nbsp;managing projects from briefing to final delivery, ensuring that TJX stakeholders, clients and agencies, adhere to set timings to ensure&amp;nbsp;a timely&amp;nbsp;delivery of all projects.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will be working on a range of&amp;nbsp;Digital Media&amp;nbsp;projects, such as Web, Email and Paid Media&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Client management responsibilities: &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Immerse yourself in the client’s brand and offering&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Prepare client proposals&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Present and deliver creative work appropriately – take ownership of your work and ensure best in class delivery of work to a high standard&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Provide weekly status reports, accompanied by a meeting or call as per client needs&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
